CREATE OR REPLACE FUNCTION public.psa_mapa_uuid(slug text)
RETURNS uuid LANGUAGE sql IMMUTABLE AS $$
  SELECT md5('mapa-psa-inplace:' || slug)::uuid
$$;

DO $$
DECLARE v_missing integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.estrutura_clusters WHERE id = 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid) THEN
    RAISE EXCEPTION 'Cluster PSA Consultores não encontrado';
  END IF;
  SELECT count(*) INTO v_missing FROM unnest(ARRAY['d1a9fabd-8262-429e-8501-7a08a6d43ad8','4cb03075-d8a7-4062-9d51-a9c64dc47523','cc5ef9ae-0425-4b4b-8035-c10af1d6bef6','1de4789f-50ce-40bd-945a-2ae01eba5b21','267dd955-3be2-4b51-ab14-c8237ecbaa3a','280035db-24c6-4c1c-9374-474acfb5663d','492df2ea-51f3-47cf-b602-3af69e1bd1b3','6e237fa4-4507-4137-84f6-0d11db63d46f','20c83382-dbdf-49ef-a915-ca97dcd53a64','3489ea0a-6d60-41c3-9784-591aa0c65572']::uuid[]) AS e(id)
    WHERE NOT EXISTS (SELECT 1 FROM public.projects p WHERE p.id = e.id);
  IF v_missing <> 0 THEN RAISE EXCEPTION 'Projetos legado ausentes: %', v_missing; END IF;
  SELECT count(*) INTO v_missing FROM unnest(ARRAY['550a8060-9f23-43e6-a78e-edcf8b258015','ca800dfa-c14e-4b4e-89d9-10d6dd1da235','ec58feca-8367-409f-8cd6-b880644896b6','ad8a6b69-2579-4a16-b708-6319555a87f9','fc0233c3-08b5-4428-be6f-332634cc9c24','94ec5922-354d-4fff-a828-a40978698866','4d6476ae-93fe-46ec-843a-02824e6d4800','16a7c7f1-2d7a-4097-a05a-76d0d28183f2','fd3d188d-1582-4d1d-96a2-7a73fd04de3d','5c2c1c02-e51e-4790-b251-15f2306ca545','bda94caf-9811-4177-b1c0-088b253c0243','d3c7e6f6-bc08-40b0-9d4a-e31e47a0c821','48d2e792-3fd2-41c1-a357-582a553d38d9','c7db1b56-22cc-4c8d-b36a-b280f8944172','bfd4a06a-de80-4fbe-9955-a877a551a3dc','3d896cea-f554-42f4-a7b9-8ec61195c71d','c1012dd1-2296-4464-bcec-be7e9bfbed77']::uuid[]) AS e(id)
    WHERE NOT EXISTS (SELECT 1 FROM public.processes p WHERE p.id = e.id);
  IF v_missing <> 0 THEN RAISE EXCEPTION 'Processos legado ausentes: %', v_missing; END IF;
  IF EXISTS (SELECT 1 FROM public.processes WHERE code = 'PROC-GERAL-001' AND cluster_id = 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid) THEN
    RAISE EXCEPTION 'PROC-GERAL-001 indevidamente vinculado ao cluster PSA';
  END IF;
END $$;

-- Limpeza idempotente
DO $$
DECLARE
  pids uuid[] := ARRAY['550a8060-9f23-43e6-a78e-edcf8b258015','ca800dfa-c14e-4b4e-89d9-10d6dd1da235','ec58feca-8367-409f-8cd6-b880644896b6','ad8a6b69-2579-4a16-b708-6319555a87f9','fc0233c3-08b5-4428-be6f-332634cc9c24','94ec5922-354d-4fff-a828-a40978698866','4d6476ae-93fe-46ec-843a-02824e6d4800','16a7c7f1-2d7a-4097-a05a-76d0d28183f2','fd3d188d-1582-4d1d-96a2-7a73fd04de3d','5c2c1c02-e51e-4790-b251-15f2306ca545','bda94caf-9811-4177-b1c0-088b253c0243','d3c7e6f6-bc08-40b0-9d4a-e31e47a0c821','48d2e792-3fd2-41c1-a357-582a553d38d9','c7db1b56-22cc-4c8d-b36a-b280f8944172','bfd4a06a-de80-4fbe-9955-a877a551a3dc','3d896cea-f554-42f4-a7b9-8ec61195c71d','c1012dd1-2296-4464-bcec-be7e9bfbed77']::uuid[];
  cid uuid := 'b21b0b89-f6fb-4f61-bfbe-cd93372f7ee3'::uuid;
BEGIN
  DELETE FROM public.etapa_documentos WHERE etapa_id IN (SELECT id FROM public.process_stages WHERE process_id = ANY(pids));
  DELETE FROM public.etapa_sistemas WHERE etapa_id IN (SELECT id FROM public.process_stages WHERE process_id = ANY(pids));
  DELETE FROM public.etapa_responsaveis WHERE etapa_id IN (SELECT id FROM public.process_stages WHERE process_id = ANY(pids));
  DELETE FROM public.gargalo_etapas WHERE etapa_id IN (SELECT id FROM public.process_stages WHERE process_id = ANY(pids));
  DELETE FROM public.process_stages WHERE process_id = ANY(pids);
  DELETE FROM public.gargalo_melhorias WHERE gargalo_id IN (SELECT id FROM public.gargalos WHERE cluster_id = cid);
  DELETE FROM public.gargalo_processos WHERE gargalo_id IN (SELECT id FROM public.gargalos WHERE cluster_id = cid);
  DELETE FROM public.gargalo_responsaveis WHERE gargalo_id IN (SELECT id FROM public.gargalos WHERE cluster_id = cid);
  DELETE FROM public.melhoria_processos WHERE melhoria_id IN (SELECT id FROM public.process_improvements WHERE cluster_id = cid);
  DELETE FROM public.melhoria_responsaveis WHERE melhoria_id IN (SELECT id FROM public.process_improvements WHERE cluster_id = cid);
  DELETE FROM public.melhoria_sistemas WHERE melhoria_id IN (SELECT id FROM public.process_improvements WHERE cluster_id = cid);
  DELETE FROM public.melhoria_acoes_td WHERE melhoria_id IN (SELECT id FROM public.process_improvements WHERE cluster_id = cid);
  DELETE FROM public.gargalos WHERE cluster_id = cid;
  DELETE FROM public.process_improvements WHERE cluster_id = cid;
  DELETE FROM public.sistema_clusters WHERE cluster_id = cid;
  DELETE FROM public.sistema_responsaveis WHERE sistema_id IN (SELECT id FROM public.sistemas_processo WHERE cluster_id = cid);
  DELETE FROM public.documento_horas_historico WHERE documento_id IN (SELECT id FROM public.documentos_processo WHERE cluster_id = cid);
  DELETE FROM public.documentos_processo WHERE cluster_id = cid;
  DELETE FROM public.sistemas_processo WHERE cluster_id = cid;
END $$;

